+import { JSDOM } from 'jsdom';
+import { describe, it, expect } from 'vitest';
+import { improveHtmlAccessibility } from './src/features/docs/doc-export/utils_html';
+
+const parse = (html: string) => new JSDOM(`<body>${html}</body>`).window.document;
+
+describe('improveHtmlAccessibility', () => {
+  it('unwraps inner heading at same level, copies class', () => {
+    const doc = parse(`<div data-content-type="heading" data-level="2"><h2 class="foo">Hi</h2></div>`);
+    improveHtmlAccessibility(doc, 'T');
+    const h2 = doc.querySelector('h2')!;
+    expect(h2).toBeTruthy();
+    expect(h2.className).toBe('foo');
+    expect(h2.textContent).toBe('Hi');
+    expect(h2.querySelector('h2')).toBeNull(); // no nesting
+  });
+
+  it('outer data-level wins on mismatch, inner removed, class not copied', () => {
+    const doc = parse(`<div data-content-type="heading" data-level="2"><h3 class="foo">Hi</h3></div>`);
+    improveHtmlAccessibility(doc, 'T');
+    expect(doc.querySelector('h3')).toBeNull();
+    const h2 = doc.querySelector('h2')!;
+    expect(h2).toBeTruthy();
+    expect(h2.textContent).toBe('Hi');
+    expect(h2.className).toBe('');
+  });
+
+  it('splits lists around an intervening heading, groups consecutive items', () => {
+    const doc = parse(`
+      <div class="bn-block-group">
+        <div class="bn-block-outer"><div class="bn-block"><div data-content-type="bulletListItem">a</div></div></div>
+        <div class="bn-block-outer"><div class="bn-block"><div data-content-type="bulletListItem">b</div></div></div>
+        <div class="bn-block-outer"><div class="bn-block"><div data-content-type="heading" data-level="2">H</div></div></div>
+        <div class="bn-block-outer"><div class="bn-block"><div data-content-type="bulletListItem">c</div></div></div>
+      </div>`);
+    improveHtmlAccessibility(doc, 'T');
+    const uls = Array.from(doc.querySelectorAll('ul'));
+    expect(uls.length).toBe(2);
+    expect(uls[0].querySelectorAll('li').length).toBe(2); // a,b grouped
+    expect(uls[1].querySelectorAll('li').length).toBe(1); // c
+    // heading between the two lists
+    const h2 = doc.querySelector('h2')!;
+    expect(uls[0].compareDocumentPosition(h2) & 4).toBeTruthy(); // ul0 before h2
+    expect(h2.compareDocumentPosition(uls[1]) & 4).toBeTruthy(); // h2 before ul1
+  });
+
+  it('inserts fallback h1 and wraps in article', () => {
+    const doc = parse(`<p>hi</p>`);
+    improveHtmlAccessibility(doc, 'My Title');
+    const h1 = doc.querySelector('h1')!;
+    expect(h1.id).toBe('doc-title');
+    expect(h1.textContent).toBe('My Title');
+    const article = doc.querySelector('article')!;
+    expect(article.getAttribute('role')).toBe('document');
+    expect(article.getAttribute('aria-labelledby')).toBe('doc-title');
+    expect(article.contains(h1)).toBe(true);
+  });
+});
